#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
# Detect a PowerShell host usable from bash (pwsh preferred, powershell.exe fallback).
_pick_ps() {
  if command -v pwsh         >/dev/null 2>&1; then PS=pwsh
  elif command -v powershell.exe >/dev/null 2>&1; then PS=powershell.exe
  else return 1; fi
}

run_wizard() {

TOTAL_STAGES=3

banner "Relocate Docker Desktop's disk to D:"
note "Docker's WSL disk (docker_data.vhdx, ~30 GB) lives on C: today."
note "This wizard walks you through pointing Docker Desktop at"
note "D:\\docker-data - Docker itself moves the file during 'Apply &"
note "Restart'. Your images, containers and volumes are preserved."
note "You only leave the keyboard for the Docker Desktop settings UI."

# ── Stage 1: preflight ────────────────────────────────────────────────────
stage "Preflight checks"
if ! _pick_ps; then
  warn "no PowerShell host (pwsh / powershell.exe) on PATH — run this wizard from Git Bash on Windows."
  return 1
fi
say "PowerShell host: $PS"
say "Checking Docker install, running processes, disk, free space…"

declare -A INFO=()
while IFS=$'\t' read -r k v; do
  [[ -n "${k:-}" ]] && INFO["$k"]="$v"
done < <("$PS" -NoProfile -Command '
$v = Get-Item "C:\Program Files\Docker\Docker\Docker Desktop.exe" -ErrorAction SilentlyContinue
if ($v) { "INSTALLED`tyes" } else { "INSTALLED`tno" }
$procs = (Get-Process | Where-Object { $_.Name -like "*docker*" } | Select-Object -ExpandProperty Name -Unique) -join ","
"PROCS`t$procs"
$vhdx = "C:\Users\markl\AppData\Local\Docker\wsl\disk\docker_data.vhdx"
if (Test-Path $vhdx) {
  "VHDX`t$vhdx`t" + [math]::Round((Get-Item $vhdx).Length/1GB,1)
} else {
  Get-ChildItem "$env:LOCALAPPDATA\Docker" -Recurse -Filter *.vhdx -ErrorAction SilentlyContinue |
    Select-Object -First 3 | ForEach-Object { "VHDX`t$($_.FullName)`t" + [math]::Round($_.Length/1GB,1) }
}
"CFREE`t" + [math]::Round((Get-Volume C).SizeRemaining/1GB,1)
"DFREE`t" + [math]::Round((Get-Volume D).SizeRemaining/1GB,1)
' | tr -d '\r')

if [[ "${INFO[INSTALLED]:-}" != "yes" ]]; then
  warn "Docker Desktop not found at C:\Program Files\Docker\Docker — nothing to relocate."
  return 1
fi
say "Docker Desktop: installed"

if [[ -n "${INFO[VHDX]:-}" ]]; then
  say "Current disk: ${INFO[VHDX]}"
else
  warn "no Docker vhdx found under AppData\Local\Docker — is Docker installed but never run?"
fi

if [[ -n "${INFO[PROCS]:-}" ]]; then
  warn "Docker processes are running: ${INFO[PROCS]}"
  say "Quit Docker first: system tray (chevron near the clock) →"
  say "right-click the whale → 'Quit Docker Desktop'."
  pause "Press Enter after quitting Docker…"
  still=$("$PS" -NoProfile -Command '(Get-Process | Where-Object { $_.Name -like "*docker*" } | Measure-Object).Count' | tr -d '\r')
  if [[ "${still:-0}" != "0" ]]; then
    warn "Docker processes still running — start this wizard again once Docker is fully quit."
    return 1
  fi
  say "Docker is now stopped."
else
  say "Docker: not running (good — the move needs it stopped to start clean)."
fi

say "C: free: ${INFO[CFREE]:-?} GB    D: free: ${INFO[DFREE]:-?} GB"
BEFORE_FREE="${INFO[CFREE]:-}"

say "Creating D:\docker-data…"
"$PS" -NoProfile -Command 'New-Item -ItemType Directory -Force -Path "D:\docker-data" | Out-Null'
say "Target folder ready: D:\docker-data"

if ! confirm "Proceed — point Docker Desktop at D:\docker-data?"; then
  warn "Cancelled — nothing was changed."
  return 0
fi

# ── Stage 2: the human-only part (Docker Desktop settings UI) ─────────────
stage "Switch the disk image location (Docker Desktop UI)"
step "1. Start Docker Desktop (Start menu → Docker Desktop)."
step "2. Click the gear icon (Settings), top-right of the dashboard."
step "3. Left menu: Resources → Advanced."
step "4. Find 'Disk image location' → Browse… → pick D:\docker-data."
step "5. Click 'Apply & Restart'."
say ""
say "Docker now MOVES the ~30 GB file to D: — expect several minutes"
say "(watch for the 'moving disk image' progress / restarting whale)."
say "When the whale is steady and the dashboard says 'Running', you're done."
note ""
note "If 'Disk image location' is greyed out or the Advanced tab is"
note "missing in your Docker version: tell the agent — plan B is to"
note "leave it on C: and reclaim space with docker system prune +"
note "compacting the vhdx instead."
pause "Press Enter once Docker finished moving and shows Running (green)…"

# ── Stage 3: verify + report ──────────────────────────────────────────────
stage "Verify + report"
declare -A V=()
while IFS=$'\t' read -r k v; do
  [[ -n "${k:-}" ]] && V["$k"]="$v"
done < <("$PS" -NoProfile -Command '
$new = Get-ChildItem "D:\docker-data" -Recurse -Filter *.vhdx -ErrorAction SilentlyContinue | Select-Object -First 1
if ($new) { "NEWVHDX`t$($new.FullName)`t" + [math]::Round($new.Length/1GB,1) } else { "NEWVHDX`tnone" }
$old = "C:\Users\markl\AppData\Local\Docker\wsl\disk\docker_data.vhdx"
"OLDGONE`t" + (-not (Test-Path $old))
"CFREE`t" + [math]::Round((Get-Volume C).SizeRemaining/1GB,1)
$dk = "C:\Program Files\Docker\Docker\resources\bin\docker.exe"
if (Get-Command docker -ErrorAction SilentlyContinue) { $d = "docker" }
elseif (Test-Path $dk) { $d = $dk }
else { $d = $null }
if ($d) { try { "ENGINE`t" + (& $d version --format "{{.Server.Version}}" 2>$null) } catch { "ENGINE`tnone" } } else { "ENGINE`tnone" }
' | tr -d '\r')

if [[ "${V[NEWVHDX]:-}" != "none" ]]; then
  say "New disk in place: ${V[NEWVHDX]}"
else
  warn "no vhdx found under D:\docker-data — the move may not have happened."
  warn "Check Docker Desktop Settings → Resources → Advanced again, or tell the agent."
fi

if [[ "${V[OLDGONE]:-}" == "True" ]]; then
  say "Old copy on C: is gone."
  if [[ -n "${BEFORE_FREE:-}" && -n "${V[CFREE]:-}" ]]; then
    say "C: free: ${BEFORE_FREE} GB → ${V[CFREE]} GB"
  fi
elif [[ -n "${INFO[VHDX]:-}" ]]; then
  warn "old file still at: ${INFO[VHDX]}"
  warn "Docker may have copied but not deleted it, or the move didn't run — tell the agent."
fi

if [[ -n "${V[ENGINE]:-}" && "${V[ENGINE]}" != "none" ]]; then
  say "Docker engine: running, version ${V[ENGINE]}"
else
  note "Docker engine not answering yet (it may still be starting) —"
  note "that's fine; the disk location is what matters here."
fi

note ""
note "Rollback any time: same settings page → point 'Disk image"
note "location' back at the C: default → Apply & Restart."
note ""
note "Bonus: this also answers 'can a Dev Drive be transferred?' —"
note "same file type. A Dev Drive made as a VHD is one portable"
note "docker_data.vhdx-style file you can detach, copy, re-attach."

finish
}

run_wizard "$@"; exit
